+fn list_modules<'db>(
+    context: &ResolverContext<'db>,
+    target: &ListingTarget<'db>,
+) -> ModuleListing<'db> {
+    let db = context.db;
+    let (name, module) = match target {
+        ListingTarget::Root => (None, None),
