+        path.walk_edge(
+            db,
+            env,
+            storage,
+            interior.constraint.when_false(),
+            |storage, path, _new_range, found_conflict| {
+                if found_conflict {
+                    false
+                } else {
+                    Self::node_is_satisfiable_on_path(db, env, storage, path, interior.if_false)
+                }
+            },
+        )
+    }
