+    pub(super) fn finish(
+        mut self,
+        db: &'db dyn Db,
+        env: &ProgramEnvironment<'db>,
+        storage: &mut ConstraintSetStorage<'db>,
+    ) -> PathBounds<'db> {
+        if self.sorted_paths.is_empty() {
+            return PathBounds::Unsatisfiable;
+        }
+
